item.stdout:
{
  "id": "SPEC-RELEASE-EXECUTION-FOUNDATION-007",
  "status": "proposed",
  "owner_track": "release-security",
  "last_verified_revision": "090b2c736a7e0f5e65467fbec79621b414a37fef",
  "depends_on": [],
  "purpose": "Establish Callisto's forge-neutral durable release execution model: an immutable release intent derived by callisto-graph, an opaque graph-validated capability required for mutation, a total receipt of exact operation outcomes, and a pure reconciliation result. The model prevents an interrupted or stale release from authorizing tags or releases that lack successful prerequisite publication.",
  "scope": "New release-domain values in callisto-model; graph-owned construction, validation, and reconciliation; CLI JSON input/output for explicit plan-driven execution. The specification supersedes the unaccepted architecture and data-model portions of SPEC-RELEASE-PLAN-DURABILITY-001A and 001B. GitHub job topology, credential policy, attestation-provider integration, and prerelease-lane policy are explicitly deferred to dependent specifications.",
  "non_goals": [
    "Adding a GitHub Actions job split or GitHub Environment configuration.",
    "Publishing to a registry, creating a tag, or creating a forge release in parallel.",
    "Adding a forge SDK, async runtime, Rayon, an append-only database, or a generic persistence abstraction.",
    "Serializing, cloning, or exposing a constructible validated-execution capability outside callisto-graph.",
    "Treating PackageId::matches as exact release-operation identity.",
    "Persisting a resolved registry URL, credential, command line, miette::Report, or raw subprocess stderr in an intent artifact.",
    "Changing whether a prerelease lane is workspace-scoped or release-set-scoped; that decision remains a prerequisite for SPEC-RELEASE-LANE-POLICY-006."
  ],
  "api_surface": [
    "callisto-model::ReleaseIntentV1, ReleaseOperationId, ReleaseOperation, ReleaseExecutionStateV1, ReleaseReceiptV1, OperationOutcome, ReconciledReleasePlanV1, ArtifactDigest, and SourceIdentity are serializable domain values with JsonSchema.",
    "callisto-graph::ValidatedReleaseIntent is an opaque, non-Serialize, non-Clone validation capability returned only by graph validation.",
    "Release mutation entry points require both &ValidatedReleaseIntent and &ApplyPermit."
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "callisto-model contains only serializable release-domain values and pure canonical/digest primitives. No callisto-model source file imports callisto_graph, opens a workspace, resolves configuration, discovers packages, invokes Git, or reads an environment variable. callisto-graph constructs ReleaseIntentV1 from Workspace and performs live-workspace validation. cargo metadata confirms no dependency edge from callisto-model to any AGPL workspace crate.",
      "is_error_case": false
    },
    {
      "id": "AC-002",
      "criterion": "Every ReleaseOperationId is exact: it contains an ecosystem-qualified PackageId, operation kind, rendered Version, and RegistryKey where the operation addresses a registry. Construction rejects a bare PackageId. Equality and ordering are structural; neither ReleaseOperationId nor reconciliation invokes PackageId::matches. A fixture containing cargo:shared and npm:shared proves that a receipt success for one cannot satisfy a prerequisite for the other.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "ReleaseIntentV1 is immutable input with a supported schema version, a SourceIdentity, a semantic-input digest, and a deterministically ordered complete operation list. It does not contain execution status, resolved registry endpoints, credentials, or human error text. Received v1 documents reject unknown fields and unsupported schema versions before live-state validation. A generated JSON schema and deserialize tests prove each rejection path.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "ArtifactDigest is the lowercase hexadecimal SHA-256 of the exact intent-artifact bytes. SemanticInputDigest is SHA-256 over a versioned, length-prefixed domain transcript, not a serde JSON rendering. The transcript begins with the ASCII domain separator callisto-release-input-v1 followed by sorted records whose type tag, UTF-8 field lengths, and bytes are specified in code comments and fixed test vectors. Equivalent input records in different insertion orders produce the same digest; changing a field, record type, or byte length produces a different digest. No floating-point field is accepted by an intent or transcript record.",
      "is_error_case": false
    },
    {
      "id": "AC-005",
      "criterion": "A graph validation function compares the intent's SourceIdentity and SemanticInputDigest against freshly observed Workspace state and returns ValidatedReleaseIntent only on exact equality. It does not call plan_publish or plan_version and it does not regenerate an operation list. On any mismatch or observation error it returns a structured GraphError before an ApplyPermit-consuming mutation is reachable. Tests instrument the planning seams and prove neither planner is called on success or failure.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "ValidatedReleaseIntent has private fields, no Serialize or Deserialize implementation, no Clone implementation, and no public constructor. The only public release mutation entry point accepts both &ValidatedReleaseIntent and &ApplyPermit. A compile-fail or external-crate integration test proves an adapter cannot construct the capability from deserialized intent bytes.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "ReleaseExecutionStateV1 records exactly one state for every intended ReleaseOperationId and rejects duplicate and unknown operation ids. Pending is the only non-terminal state. Terminal success is only Published or AlreadySatisfied; Failed and Blocked are non-success terminal outcomes. ReleaseReceiptV1 can be constructed only from an execution state with no Pending operation and records exactly one terminal outcome for every intended operation. Reconciliation is pure over execution state and returns an eligible tag/release operation only when every exact prerequisite has terminal success. Tests cover an interrupted Pending operation, a blocked npm main package, and a successful cargo:shared receipt that must not authorize npm:shared.",
      "is_error_case": true
    },
    {
      "id": "AC-008",
      "criterion": "Receipt persistence uses callisto_model::atomic::atomic_write and retains the previous valid receipt if a write fails before rename. Receipt updates are sequential in planned operation order. No append-only journal, cache, or repository-tracked transient file is introduced. A failure-injection test proves an incomplete write cannot be read as a successful receipt.",
      "is_error_case": true
    },
    {
      "id": "AC-009",
      "criterion": "Machine-readable failure data is a closed typed discriminator with bounded, redacted optional detail. CLI-facing validation and execution errors derive miette::Diagnostic with a unique stable code and actionable help. Durable intent and receipt JSON never serialize miette reports or raw subprocess stderr. Tests use a credential-shaped URL and a known secret value to prove persisted values are rejected or redacted.",
      "is_error_case": true
    },
    {
      "id": "AC-010",
      "criterion": "The implementation uses existing sequential graph and registry execution. Rayon and Tokio are not added to workspace dependencies by this specification. A performance regression test or benchmark records the number of workspace discovery passes for intent creation and validation; each command performs at most one Workspace load and no registry/network operation during validation.",
      "is_error_case": false
    }
  ],
  "reasoning": "The current PublishPlan is a useful presentation and execution-plan value but is not a durable authorization protocol: it carries raw optional registry/index strings and its PublishReport treats only Failed as failure. The existing ApplyPermit capability proves Callisto already favors compile-time authority tokens for irreversible mutation. Validation needs Workspace/config/package discovery and therefore belongs in callisto-graph; placing it in callisto-model would violate the Layer 1 dependency boundary. Artifact transport integrity and semantic freshness are intentionally separate: raw artifact bytes are hashed directly, while a small versioned domain transcript avoids making a formatter implementation the release protocol."
}

